package app
import("archive/zip";"bytes";"context";"crypto/sha256";"encoding/hex";"encoding/json";"fmt";"light-media/internal/plugins";"light-media/internal/plugins/artifacts";"net/http";"net/http/httptest";"os";"os/exec";"path/filepath";"runtime";"slices";"sync";"testing")
type sourceAuthTraceKey struct{}
type sourceAuthTrace struct{mu sync.Mutex;Calls map[string][]string;Errors []string}
func observeSourceAuthSDK(ctx context.Context,id,method string,err error){v,_:=ctx.Value(sourceAuthTraceKey{}).(*sourceAuthTrace);if v==nil{return};v.mu.Lock();defer v.mu.Unlock();if err!=nil{v.Errors=append(v.Errors,id+":"+method+":"+err.Error());return};v.Calls[id]=append(v.Calls[id],method)}
func authActualInstall(t *testing.T,a *App,cookie *http.Cookie,binary string)*originalPluginInstance{
 t.Helper();payload,err:=os.ReadFile(binary);if err!=nil{t.Fatal(err)};raw,err:=exec.Command(binary,"--manifest").Output();if err!=nil{t.Fatal(err)};var m plugins.Manifest;if json.Unmarshal(raw,&m)!=nil{t.Fatal("actual manifest")};digest:=sha256.Sum256(payload);hash:=hex.EncodeToString(digest[:]);artifact:=artifacts.Artifact{Platform:runtime.GOOS+"-"+runtime.GOARCH,Format:"executable",SHA256:hash,ExecutableSHA256:hash,Size:int64(len(payload)),HostContract:pluginResourcesSDKContract}
 if m.Frontend!=nil{files:=map[string][]byte{m.Entry:payload};for _,name:=range []string{"remoteEntry.js","view.js","style.css"}{p:=filepath.Join(os.Getenv("AUTH_REAL_FRONTEND"),name);b,e:=os.ReadFile(p);if e!=nil{t.Fatal(e)};files[m.Frontend.Root+"/"+name]=b};var buf bytes.Buffer;z:=zip.NewWriter(&buf);keys:=make([]string,0,len(files));for k:=range files{keys=append(keys,k)};slices.Sort(keys);for _,name:=range keys{b:=files[name];h:=&zip.FileHeader{Name:name,Method:zip.Deflate};h.SetMode(0644);if name==m.Entry{h.SetMode(0755)};w,e:=z.CreateHeader(h);if e!=nil{t.Fatal(e)};w.Write(b);sum:=sha256.Sum256(b);artifact.Files=append(artifact.Files,artifacts.PackageFile{Path:name,Size:int64(len(b)),SHA256:hex.EncodeToString(sum[:])})};if err:=z.Close();err!=nil{t.Fatal(err)};payload=buf.Bytes();sum:=sha256.Sum256(payload);artifact.Format="zip";artifact.SHA256=hex.EncodeToString(sum[:]);artifact.Size=int64(len(payload))}
 index:=artifacts.Index{SchemaVersion:1,PluginID:m.PluginID,CurrentVersion:m.Version,Releases:[]artifacts.Release{{Version:m.Version,Manifest:m,Artifacts:[]artifacts.Artifact{artifact}}}};repo:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){switch r.URL.Path{case"/index":json.NewEncoder(w).Encode(index);case"/worker":w.Write(payload);default:http.NotFound(w,r)}}));t.Cleanup(repo.Close);index.Releases[0].Artifacts[0].URL=repo.URL+"/worker";body,_:=json.Marshal(map[string]any{"plugin_id":m.PluginID,"repo_url":repo.URL+"/index"});r:=callTest(t,a.Handler(),http.MethodPost,"/api/plugins/install",string(body),cookie,"");assertOriginalRegistrySuccess(t,r.Code,r.Body.Bytes());a.wg.Wait();v,ok:=a.pluginRunningInstances.Load(m.PluginID);if !ok{t.Fatal("actual worker absent",m.PluginID)};return v.(*originalPluginInstance)
}
func TestIndependentActualProductionAuthDiscovery(t *testing.T){
 a:=newTestApp(t);t.Cleanup(a.closeOriginalSessions);cookie:=setupTestAdmin(t,a);objects:=map[string]*originalPluginInstance{}
 for _,pair:=range [][2]string{{"CategoryEditor","AUTH_CATEGORY_BINARY"},{"TorrentTransfer","AUTH_TT_BINARY"},{"RemoveLink","AUTH_RLK_BINARY"}}{objects[pair[0]]=authActualInstall(t,a,cookie,os.Getenv(pair[1]))}
 // Real CategoryEditor partial initialization keeps enabled=true before the
 // non-string write failure; no fake getter or production policy write is used.
 r:=callTest(t,a.Handler(),http.MethodPut,"/api/plugins/CategoryEditor",`{"enabled":true,"content":1}`,cookie,"");if r.Code<400{t.Fatal("source partial-init type failure not reached",r.Code,r.Body.String())}
 path:=filepath.Join(a.Dir,"owned-empty-torrent-meta");if err:=os.MkdirAll(path,0700);err!=nil{t.Fatal(err)};cfg,_:=json.Marshal(map[string]any{"enabled":true,"cron":"0 0 1 1 *","fromdownloader":"owned-from","todownloader":"owned-to","fromtorrentpath":path,"autostart":false,"onlyonce":false});r=callTest(t,a.Handler(),http.MethodPut,"/api/plugins/TorrentTransfer",string(cfg),cookie,"");assertOriginalRegistrySuccess(t,r.Code,r.Body.Bytes())
 r=callTest(t,a.Handler(),http.MethodPut,"/api/plugins/RemoveLink",`{"enabled":true,"monitor_dirs":"","monitor_strm_deletion":false,"delayed_deletion":false}`,cookie,"");assertOriginalRegistrySuccess(t,r.Code,r.Body.Bytes())
 r=callTest(t,a.Handler(),http.MethodPost,"/api/plugins/TorrentTransfer/clone",`{"suffix":"music"}`,cookie,"");assertOriginalRegistrySuccess(t,r.Code,r.Body.Bytes());a.wg.Wait();v,ok:=a.pluginRunningInstances.Load("TorrentTransfermusic");if !ok{t.Fatal("actual music clone absent")};objects["TorrentTransfermusic"]=v.(*originalPluginInstance);r=callTest(t,a.Handler(),http.MethodPut,"/api/plugins/TorrentTransfermusic",string(cfg),cookie,"");assertOriginalRegistrySuccess(t,r.Code,r.Body.Bytes())
 for id,o:=range objects{enabled,e:=o.getState(context.Background());if e!=nil||!enabled{t.Fatal("actual source-enabled object required",id,enabled,e)}}
 trace:=&sourceAuthTrace{Calls:map[string][]string{}};ctx:=context.WithValue(context.Background(),sourceAuthTraceKey{},trace);req:=httptest.NewRequest(http.MethodGet,"/api/auth/providers",nil).WithContext(ctx);response:=httptest.NewRecorder();a.Handler().ServeHTTP(response,req);if response.Code!=200{t.Fatal("public real auth discovery",response.Code,response.Body.String())};if len(trace.Errors)!=0{t.Fatal("SDK call failed",trace.Errors)}
 for id:=range objects{calls:=trace.Calls[id];t.Logf("actual enabled auth IPC instance=%s calls=%v",id,calls);if !slices.Equal(calls,[]string{"get_state"}){t.Errorf("source inherited auth must call state only: %s got %v",id,calls)}}
 if os.Getenv("AUTH_TRACE_OUTPUT")!=""{b,_:=json.MarshalIndent(map[string]any{"classification":"real production handlers/Manifests in actual App and independent SDK processes; only host test-context successful-call recorder instrumented; no worker debug API","enabled_objects":len(objects),"methods":trace.Calls,"errors":trace.Errors,"http_status":response.Code},"","  ");if err:=os.WriteFile(os.Getenv("AUTH_TRACE_OUTPUT"),b,0600);err!=nil{t.Fatal(err)}}
 fmt.Println("actual production auth discovery observations recorded")
}
